import math
def calculate_area(radius: float) -> float:
    if radius < 0:
        raise ValueError('Radius cannot be negative')
    return math.pi * (radius ** 2)

import sqlite3
def fetch_active_products(db_path: str):
    conn = sqlite3.connect(db_path)
    cur = conn.cursor()
    cur.execute('SELECT id, title, price FROM products WHERE is_active = 1')
    return cur.fetchall()
